"""Add original release-control and GraphQL API Web Development tracks."""
import copy
import datetime
import html
import json
import re
import subprocess
import uuid
from pathlib import Path

root = Path(__file__).resolve().parents[1]
fixture = root / 'src/data/fixtures.json'
entries = json.loads(fixture.read_text())
by_path = {entry['path']: entry for entry in entries}
stamp = datetime.datetime.now(datetime.UTC).isoformat()

def p(value):
    return '<p>' + html.escape(value) + '</p>'

def link(path):
    title = by_path[path]['title'] if path in by_path else next((item['title'] for item in lessons if item['path'] == path), None)
    assert title is not None, path
    return '<a href="/' + html.escape(path, quote=True) + '">' + html.escape(title) + '</a>'

hubs = [
    dict(path='web-tech/feature-release-and-experiment-controls', title='Feature Release and Experiment Controls', summary='Separate deployment, exposure, permission, and measured outcome in controlled web releases.', overview='A shipped code path may be hidden, exposed to a small group, compared against another experience, or turned off during an incident. Those are different decisions. This track follows a case-review interface whose new assignment panel is released in stages. It covers stable evaluation, safe defaults, server enforcement, experiment exposure, metric integrity, and flag retirement. Every flag has an owner and an expiry plan; none grants data permission. The examples are compact decision checks, while real evaluation and measurement require an audited service and deployment path.', bridges=['web-tech/release-smoke-and-rollback','web-tech/production-signals-and-incident-decisions']),
    dict(path='web-tech/graphql-query-and-resolver-boundaries', title='GraphQL Query and Resolver Boundaries', summary='Design typed query contracts while bounding work and checking access in every resolver path.', overview='GraphQL lets a client choose a response shape from a typed schema, but schema syntax does not price the work or authorize private objects. This track follows a case-review query that joins cases, assignees, and activity. It covers schema and nullability, resolver batching, query admission, and mutation error states. A deployment needs a chosen server implementation and database layer; the lessons focus on contracts that remain important across libraries. The same object authorization rule applies whether a case is reached from a root field or through a nested relation.', bridges=['web-tech/backend-api-systems','web-tech/api-evolution-and-compatibility']),
]

lessons = [
    dict(hub=0, path='web-tech/feature-flag-evaluation-scope-and-safe-default', title='Feature Flag Evaluation Scope and Safe Default', summary='Evaluate a named release decision consistently without using it as a data-permission check.',
    definition='A feature flag selects a behavior or interface variant for a defined actor and context. It is a release control, not authorization. A user who sees a hidden button can still call an API directly; the API must enforce the same object and tenant permissions as before. A flag evaluation should specify key, default, targeting inputs, ruleset version, and the point in the request where it is read. Stable context keeps one user from alternating between old and new flows on every refresh. When the flag service is unavailable, a documented safe default must preserve the application’s core task and data rules.',
    case='The case-review team ships a new assignment panel but exposes it only to internal reviewers first. Reviewer 29 belongs to organization 6 and matches the rollout group. The server evaluates panel revision 47 and sends a variant in the page bootstrap. The browser renders the new panel; a second API request still checks reviewer 29 can update case 62. Reviewer 47, outside the rollout, sees the old panel and may still use the same authorized assignment endpoint. If remote flag configuration is unavailable, both server and browser fall back to the approved old panel rather than disagreeing about which form fields exist.',
    implementation='Choose a stable evaluation key such as an account or organization identifier, depending on whether the user experience must remain coherent across devices. Minimize context sent to a flag service; avoid emails and case content where a coarse key suffices. Evaluate on the server for behavior that affects response shape or writes, then pass the resolved variant and ruleset version to the client. A client flag may hide presentation but may not open a server privilege. Define behavior for missing keys, stale configuration, and service failure. Keep a test matrix for old and new paths while both are live, and name an owner and removal trigger so the conditional does not become permanent debris.',
    cost='A local evaluation is near O(1) for a small ruleset; a remote lookup adds network latency and availability risk, so most systems cache a versioned configuration. A cache reduces request cost but delays a kill action until refresh or invalidation. Evaluating per component can create conflicting answers within one page; capture one request-level decision where consistency matters. Every flag doubles some test paths and adds operational ownership. Measure fallback evaluations, stale configuration age, variant distribution, and errors split by variant. A flag that adds expensive data work should also have a capacity budget.',
    failure='The UI hides the new assignment panel for reviewer 47, but the new API route only checks a flag header from the browser. Reviewer 47 changes the header and edits case 62 without permission. Remove client claims from the access decision and enforce object authorization. Another deployment defaults the server to old while the browser defaults to new, causing a hydration mismatch and discarded form values. Test flag service outage, stale client bootstraps, account switch, two open tabs, direct API calls, and a ruleset update during an in-flight mutation.',
    drill='Define the panel flag with an owner, default, ruleset version, and stable assignment unit. Render a server response for reviewer 29 and then request its mutation endpoint directly as reviewer 47. Turn the flag service off and verify the old form remains usable. Change rules mid-session and inspect whether the chosen request-level variant stays coherent. Remove case permission from reviewer 29 while the new panel remains visible; the write must fail. Record evaluation reason and version without logging case contents.',
    decision='Use a versioned flag for release exposure while every data operation keeps its own current authorization check.',
    code='function panelVariant(context, config) {\n  return config.ready && config.allowedOrganizations.has(context.organizationId) ? "new" : "old";\n}\nconsole.log(panelVariant({ organizationId: 6 }, { ready: false, allowedOrganizations: new Set([6]) }));\n// Output: old',
    checks=['A direct API call cannot use the flag to bypass access control.','Server and client use one coherent resolved variant.','Unavailable configuration has a tested safe default.'], mistakes=['Treating a hidden button as server authorization.','Using unstable random assignment on every request.','Leaving flag ownership and removal undefined.'], related=['web-tech/object-level-authorization-for-reads-and-writes','web-tech/release-smoke-and-rollback','web-tech/tenant-scope-in-cache-and-background-work']),
    dict(hub=0, path='web-tech/gradual-rollout-kill-switch-and-state-compatibility', title='Gradual Rollout, Kill Switch, and State Compatibility', summary='Expose a release in stages and prove disabling it leaves stored data and sessions usable.',
    definition='A gradual rollout changes who can exercise new code without necessarily changing the deployed artifact. A kill switch stops a named behavior quickly when measured harm appears. Neither is a substitute for rollback design: new writes may have changed stored data, queued jobs, cache entries, or client state that old code must still handle. A safe release defines exposure stages, guardrail metrics, stop thresholds, and a state-compatibility window before the first user enters. Disabling a flag can prevent new work but cannot undo completed payment, uploaded bytes, or sent messages.',
    case='The new assignment panel is enabled for 5 percent of reviewer accounts, then 23 percent after an observation window. Assignment writes still use the same revisioned API, so turning the panel off routes future edits through the old interface. During the second stage, save failures rise for the new variant. The on-call owner disables the panel and verifies that cases edited by the new form still open in the old form. A background assignment email already queued remains valid; the switch does not erase it. The team keeps the new code deployed while investigating and records the ruleset version that exposed each request.',
    implementation='Stage by stable units and preserve membership as the percentage changes; a naive threshold change can reshuffle users if the hash or salt changes. Start with staff and a small cohort, then advance only when request success, latency, accessibility, and error signals meet named bounds. Keep the old and new data representations compatible for the rollout window, or supply a reversible migration plan. Test the off path after new writes have occurred, not only before launch. Separate a release flag from a long-lived operational circuit breaker. Ensure configuration updates reach the server within a documented time and that stale clients cannot force a disabled mutation. Record who changed the flag and why.',
    cost='Evaluating a cohort is cheap, but dual-path tests, state compatibility, and monitoring add delivery cost. A remote flag change can be faster than rebuilding, yet propagation has a measurable delay through caches and active browser tabs. Keeping both forms and schemas alive longer raises maintenance cost, so schedule removal after stability. A sudden 100 percent rollout can create nonlinear load if the new panel fetches extra data. Compare error and latency by variant and cohort size, and measure off-switch completion time. Guardrail metrics must reflect user outcomes, not only server uptime.',
    failure='The team disables the panel after errors, but new writes stored a field the old form rejects. Reviewers cannot reopen recently edited cases. Test old-path reads against new-path data before rollout. Another kill switch only changes the browser bundle; already-open tabs continue sending new mutation shapes. Enforce the disablement at the server boundary. Test progression from staff to 5 and 23 percent, a stale configuration cache, an active tab during shutdown, queued work, rollout reversal, and a schema migration still in progress.',
    drill='Assign stable cohorts to 47 reviewer IDs and record membership before and after raising the threshold. Create cases through both form variants, disable the new path, and reopen every case through the old one. Inject a save failure that breaches the stop rule, time how long evaluation changes take to reach workers and browsers, and inspect the audit record. Finally remove the flag in a branch and run both old and new data fixtures through the remaining code.',
    decision='Stage exposure against measured guardrails and prove the off path handles data created while the flag was on.',
    code='function shouldStopRollout(failures, attempts, limit) {\n  return attempts > 0 && failures / attempts > limit;\n}\nconsole.log(shouldStopRollout(7, 47, 0.1));\n// Output: true',
    checks=['A disabled release leaves prior writes readable.','The server stops new-variant writes after the documented propagation bound.','Cohort membership and stop decisions have audit evidence.'], mistakes=['Assuming an off switch reverses completed side effects.','Testing the old path only before new data exists.','Raising exposure without a capacity or error guardrail.'], related=['web-tech/expand-and-contract-migrations','web-tech/incident-containment-and-evidence-timeline','web-tech/api-evolution-and-compatibility']),
    dict(hub=0, path='web-tech/experiment-assignment-exposure-and-metric-integrity', title='Experiment Assignment, Exposure, and Metric Integrity', summary='Keep variant assignment, actual exposure, and outcome measurement separate and comparable.',
    definition='An experiment compares outcomes for stable groups under a defined eligibility rule. Assignment is the group a unit receives; exposure is the point at which that unit can actually encounter the treatment. Logging assignment at page load when the feature is below the fold can count people who never saw it. Logging exposure only after a variant-specific action can bias the groups. The analysis unit, enrollment rule, primary outcome, observation window, and guardrail metrics should be fixed before launch. A feature flag can deliver variants, but a rollout percentage alone does not produce a sound experiment.',
    case='The case-review team tests whether the new assignment panel reduces time to assign a case. Reviewers are assigned by stable account ID, but only those who open an editable case enter the eligible population. Exposure is recorded when either panel is rendered, using the same rule in control and treatment. The result event contains an experiment ID, variant, and coarse completion time but no case title. When the treatment panel crashes before exposure logging, observed groups become unbalanced. The team pauses interpretation, investigates the missing events, and keeps error rate as a guardrail rather than celebrating a faster average among survivors.',
    implementation='Use a stable unit that matches the product decision: account, organization, or session, with a documented rule for shared devices and multiple accounts. Keep eligibility identical across variants and record one exposure per unit per experiment context when the experience is actually presented. Deduplicate retries and carry the same unit ID into outcome events. Define one primary metric and a small set of guardrails before observing results. Check traffic allocation, missing events, crossovers, and sample-ratio mismatch; persistent imbalance can signal assignment or logging defects. Avoid changing variants mid-experiment without recording a new analysis period. Minimize telemetry fields and honor optional-measurement policy where it applies.',
    cost='Stable assignment can be O(1) hashing or a stored lookup, while event collection scales with exposures and outcomes. Dedupe state adds storage proportional to the enrolled units. Measuring at a different point for each variant creates bias that no larger sample fixes. Very small groups produce noisy estimates; deciding a winner after each refresh increases false-positive risk. Analysis also costs engineering time to inspect guardrails and data quality. Track exposure-to-outcome join rate, missing identifiers, sample ratio, crossover, and error rate before examining the primary result.',
    failure='The treatment records exposure when its button is clicked, while control records it when the panel appears. People who never click disappear from the treatment denominator, making the variant seem faster. Move both exposure points to equivalent presentation. Another client assigns by a random number on every reload; a reviewer sees both panels and cannot be analyzed as one unit. Test account switching, route reload, offline event replay, duplicate exposure, variant-specific crash, cohort imbalance, and a privacy setting that disables optional measurements.',
    drill='Predeclare an eligible reviewer population, unit ID, exposure point, assignment split, primary completion metric, and error guardrail. Simulate 47 eligible reviewers, with some leaving before panel render and one treatment crash. Verify only rendered panels count as exposed under both variants. Duplicate two events and confirm dedupe. Change the assignment seed in a test and detect crossover. Inspect exposure counts for unexpected imbalance before reading any claimed improvement.',
    decision='Measure comparable exposed groups under a stable assignment and verify data quality before interpreting an outcome.',
    code='function shouldRecordExposure(eligible, rendered, alreadyRecorded) {\n  return eligible && rendered && !alreadyRecorded;\n}\nconsole.log(shouldRecordExposure(true, false, false));\n// Output: false',
    checks=['Control and treatment use one equivalent exposure point.','Outcomes join to a stable assigned unit.','Imbalance and crossover are checked before interpreting results.'], mistakes=['Calling every page load an exposure.','Changing the assignment unit during a run.','Treating a rollout percentage as a complete experiment.'], related=['web-tech/telemetry-minimization-and-retention','web-tech/user-journey-slos-and-burn-alerts','web-tech/quality-and-capacity-engineering']),
    dict(hub=0, path='web-tech/flag-telemetry-audit-and-retirement', title='Flag Telemetry, Audit, and Retirement', summary='Record enough decision evidence to debug a release, then remove temporary branches and rules.',
    definition='A feature flag has a lifecycle. It begins with a purpose and owner, gains targeting rules and observation signals, reaches a final default, then should be removed from code and configuration when it no longer controls an active decision. An operational circuit breaker may be long-lived, but a release flag left indefinitely creates two paths to maintain and a hidden source of configuration drift. Decision telemetry should record the flag key, evaluated variant, ruleset version, coarse reason, and request context needed for debugging without copying sensitive targeting fields into logs. Audit records should show who changed targeting or disabled the feature.',
    case='The assignment-panel flag has stayed at 100 percent for six weeks. A new engineer discovers that the old panel is still built, tested, and used only when remote evaluation fails. The team first confirms the new path’s error, latency, and accessibility measures are stable. It changes the fallback to the final approved behavior, removes old-panel code and state adapters, and deletes the targeting rule after deployment. The audit retains when the rollout changed and which version served past incidents, but raw reviewer IDs and case contents are not copied into general metrics. A separate emergency switch remains, with its own owner and drill.',
    implementation='For each flag, store purpose, owner, creation date, planned review date, safe default, data dependencies, and removal condition. Emit bounded evaluation signals with a stable flag key and variant; avoid unbounded user or case labels in metric dimensions. Audit changes to targeting, percentage, and off state, including actor and reason. During retirement, search server, browser, jobs, tests, and persisted schemas for branches that depend on the flag. Choose the final path, remove dead state transformations, migrate or expire old stored variants, and deploy with a rollback plan that does not require recreating deleted configuration. Keep permanent circuit breakers separate and test their off paths regularly.',
    cost='Every active flag adds branching cost to review and tests. High-cardinality labels can make telemetry expensive even if each evaluation is fast, so aggregate variant and reason counts and reserve detailed traces for sampled, access-controlled investigation. Removing a branch lowers long-term complexity but requires a careful compatibility check while old clients remain open. A ruleset audit is small storage compared with event logs. Track flags past review date, missing owners, fallback frequency, branch coverage, stale SDK configuration, and the time it takes to disable a feature during a drill.',
    failure='A team deletes the remote rule but leaves a client default that chooses the old panel for offline sessions. Some reviewers quietly return to the retired path. Remove or update all defaults and test offline behavior. Another team removes old code before a stored value written by old clients has expired; the new parser rejects valid historical data. Keep the compatibility window explicit. Test missing config, old browser bundle, job retry carrying an old flag value, rollback after rule deletion, and a metric label that accidentally contains a raw account ID.',
    drill='Inventory all references to the panel flag in the app and worker. Record its final behavior, fallback, state-compatibility rule, and removal date. Delete one branch and run old and new fixture data through the remaining route. Simulate an offline browser and a retrying job that held an older ruleset version. Check the evaluation dashboard for variants and errors, then inspect metric labels and audit entries for private data. Practice the separate emergency switch after the release flag is gone.',
    decision='Retire temporary flags after their decision is settled, while keeping minimal evidence and a separately tested emergency control.',
    code='function flagNeedsReview(flag, today) {\n  return flag.kind === "release" && today > flag.reviewBy;\n}\nconsole.log(flagNeedsReview({ kind: "release", reviewBy: 40 }, 47));\n// Output: true',
    checks=['Each release flag has an owner, review date, and removal rule.','Evaluation metrics avoid raw account and case dimensions.','Retirement covers server, browser, jobs, defaults, and old data.'], mistakes=['Leaving a 100 percent release flag indefinitely.','Logging targeting identities as metric labels.','Deleting a rule before old clients and stored state are compatible.'], related=['web-tech/release-smoke-and-rollback','web-tech/telemetry-shapes-redaction-and-cardinality','web-tech/api-evolution-and-compatibility']),
]

lessons.extend([
    dict(hub=1, path='web-tech/graphql-schema-nullability-and-evolution', title='GraphQL Schema Nullability and Evolution', summary='Design fields whose absence and failure behavior can change without breaking existing clients.',
    definition='A GraphQL schema defines available operations, field types, arguments, and nullability. A non-null marker promises that a successful execution path will provide a value; if a resolver cannot do so, error propagation may null a larger parent selection. That can surprise a client that expected only one optional field to fail. Schema evolution should be additive where possible, with deprecation and usage evidence before removal. Types express shape, not access rights or runtime cost. A field appearing in introspection does not mean every caller may read every object returned by that field.',
    case='The case-review API exposes Case with id, status, owner, and an optional inspectionDueAt. The team wants to add riskBand. Early cases have no score, so declaring riskBand non-null would let an old record’s missing score null its containing Case selection. The team adds a nullable field, documents when it is absent, and updates only clients that need it. Months later, ownerName is replaced by an Owner object. The old field remains during a compatibility window while usage telemetry identifies clients still requesting it. Both fields use the same current tenant and case authorization rule.',
    implementation='Name fields after stable domain concepts instead of current database columns. Choose nullability by actual data and failure behavior, including old records and permission-filtered relations. Distinguish an empty list from an unavailable list and from a null parent. Add fields before removing old ones; deprecate with a reason and record usage by operation, not private query variables. Keep schema changes and resolver behavior synchronized across deployments. Validate generated client types against the deployed schema and test old operation documents during rollout. Authorization belongs in data access or resolver policy, not in whether a field is visible in schema text. Limit introspection as appropriate to the service, but never treat hiding it as security.',
    cost='Schema validation is bounded by the requested document size and type references; each added field is cheap to define but can add resolver and compatibility work. Keeping deprecated fields consumes code and test time until clients migrate. A non-null promise can simplify clients but raises failure blast radius when a downstream dependency is unavailable. Measure field use, null responses by cause, client operation versions, and error paths before tightening a field contract. Avoid moving a field from nullable to non-null merely because current fixtures happen to contain values.',
    failure='The team changes owner from nullable to non-null because new cases always have an owner. Historical unassigned cases still exist; their owner resolver returns null, and an otherwise useful case list becomes null for some clients. Preserve the honest nullable contract or migrate all data and failure paths first. Another change removes ownerName after only the newest web bundle migrates, breaking mobile or cached clients. Test old operations, empty and historical records, downstream timeout, permission changes, deprecated field use, and a partial error path.',
    drill='Draft Case fields for id, status, owner, inspectionDueAt, and riskBand using the actual old-data states. Query a historical unassigned case, a current assigned case, and a downstream owner lookup failure. Record how each null propagates under chosen declarations. Add Owner while retaining ownerName and run an older operation document against the new schema. Deny one case to reviewer 62 and confirm both old and new owner fields obey the same object authorization.',
    decision='Make nullability match real data and failure paths, then evolve fields with observed client compatibility.',
    code='function riskBandForCase(caseRecord) {\n  return caseRecord.score == null ? null : caseRecord.score >= 47 ? "high" : "normal";\n}\nconsole.log(riskBandForCase({ score: null }));\n// Output: null',
    checks=['Historical and failure cases satisfy declared nullability.','Old operation documents work during the migration window.','Schema visibility never substitutes for object authorization.'], mistakes=['Marking a field non-null based only on new records.','Removing a field before old clients stop requesting it.','Treating a typed schema as a permission system.'], related=['web-tech/api-evolution-and-compatibility','web-tech/object-level-authorization-for-reads-and-writes','web-tech/contract-tests-across-boundaries']),
    dict(hub=1, path='web-tech/graphql-resolver-batching-and-tenant-scope', title='GraphQL Resolver Batching and Tenant Scope', summary='Prevent nested field fan-out while keeping request-local caches inside one actor and tenant boundary.',
    definition='A GraphQL resolver supplies data for a selected field. A query for many parent objects can invoke a child resolver once per parent, producing the N-plus-one pattern. Batching joins keys into fewer backend calls, but a loader cache also has a security boundary: a result fetched for one actor or tenant must not be reused for another. Request-local loaders make that boundary easier to reason about. The batch function must return results in the same order as input keys and represent missing or forbidden objects deliberately. Batching improves call count; it does not replace query admission, indexing, or per-object authorization.',
    case='Reviewer 29 requests 47 cases with owner names. A naive resolver loads the case list once and calls the owner service 47 times. A request-local owner loader collects 47 owner IDs into one bounded backend call, maps returned records back to key order, and filters each case under organization 6. Reviewer 62 opens another request for a different organization and gets a new loader instance. If one owner ID is shared between tenants, the cache key includes the tenant scope or the underlying lookup enforces it, so neither request sees another tenant’s owner record.',
    implementation='Construct loaders per incoming request or authenticated execution context, not as global singletons. Scope cache keys to tenant and, where object policy differs, actor or permission version. Batch only compatible reads and cap the batch size to avoid one giant query. Preserve key order and duplicate-key behavior expected by the loader. Apply authorization on every root and nested path, and avoid leaking forbidden object existence through different error shapes unless the product intends that distinction. Use indexed database queries or a downstream batch endpoint; a loader that loops over keys internally still performs N calls. Trace backend call counts and batch sizes for representative queries.',
    cost='Without batching, one root lookup plus n nested lookups gives O(n) backend round trips for n cases. A bounded batch can reduce it to roughly O(1) calls per field level while still doing O(n) data work and memory for n results. Cache entries live for a request; a global cache could improve hit rate but creates invalidation and tenant-leak risk. Large batches may stress SQL parameter limits or downstream payload caps, so split them. Measure resolver count, backend calls, batch size, query latency, denied nested objects, and cache hits under account changes.',
    failure='The service creates one global loader at process start. Reviewer 29 loads owner 62 under organization 6; later reviewer 47 requests owner 62 under another tenant and receives the cached first result. Build the loader inside the request and scope keys to the tenant. Another batch function returns database rows in arbitrary order, attaching the wrong owner to a case. Reorder results by requested key. Test repeated keys, missing owners, forbidden nested records, 47-case pages, concurrent tenants, permission revocation, and a loader backed by an unindexed query.',
    drill='Run a case list with 47 distinct owners and count backend calls before and after batching. Have the batch service return rows out of order and verify the resolver restores key order. Send two requests concurrently under separate tenants, with one overlapping owner ID, and assert no cache sharing. Revoke reviewer 29’s case permission between requests and confirm the next request does not reuse a stale result. Cap one batch at a documented size and inspect latency and memory on larger pages.',
    decision='Batch nested reads per request and preserve tenant and actor scope at every cache and resolver boundary.',
    code='function orderedOwners(ids, rows) {\n  const byId = new Map(rows.map(owner => [owner.id, owner]));\n  return ids.map(id => byId.get(id) ?? null);\n}\nconsole.log(orderedOwners([62, 47], [{ id: 47 }, { id: 62 }]).map(owner => owner.id).join(","));\n// Output: 62,47',
    checks=['A 47-case selection avoids 47 separate owner calls.','Batch results match requested keys even if storage returns another order.','No loader cache crosses actor or tenant requests.'], mistakes=['Using a process-global loader for private data.','Batching keys but looping over them inside the batch function.','Trusting backend row order to match requested key order.'], related=['web-tech/indexes-and-query-plans','web-tech/tenant-scope-in-cache-and-background-work','web-tech/object-level-authorization-for-reads-and-writes']),
    dict(hub=1, path='web-tech/graphql-operation-cost-and-admission', title='GraphQL Operation Cost and Admission', summary='Bound depth, breadth, list sizes, and resolver work before executing a client-selected query.',
    definition='A GraphQL endpoint accepts client-selected fields, so a small HTTP request can ask for expensive nested lists or repeated aliases. Rate limiting by request count alone misses the amount of work inside one operation. Admission control should validate document size, depth, field count or weighted cost, list pagination bounds, and caller-specific budgets before resolver execution. Persisted operation documents can narrow the set of public requests, but their IDs still need versioning, authorization, and cost review. A depth limit by itself can admit a shallow query with thousands of aliased fields, while a simple field count may underprice one heavy search.',
    case='A case-review client requests 23 cases, each with 47 activity records and owner details. The server estimates work from bounded first arguments and field weights, then either accepts within reviewer 29’s budget or returns a typed cost error. A malicious caller sends 600 aliases of one shallow case field; breadth limits reject it even though depth is low. Public browser clients use known operation IDs during normal use, but the server still validates the registered document and reviewer’s current case rights at execution. An operations dashboard may have a separate budget with explicit service identity.',
    implementation='Parse and validate the operation before resolvers run. Cap document bytes, aliases, recursion depth, selected fields, list arguments, and total estimated cost under a server policy that matches real backend work. Require bounded pagination for every collection and reject unbounded first values. Assign higher weights to search, remote joins, or wide aggregations and update weights from production traces. Apply per-actor rate and concurrency budgets as a second layer. Register approved operation documents for constrained clients if useful, with a migration path for deployments; never assume a hash alone authenticates the caller. Return a safe, predictable rejection rather than partial expensive execution. Measure accepted estimated cost against actual latency and backend calls.',
    cost='Parsing and scoring an operation is O(m) in the document size, while executing a selected graph can grow with list cardinalities at each level. Strict limits reject some legitimate dashboards, so offer a purpose-built aggregate or pagination route instead of simply raising all limits. Persisted operations reduce arbitrary query surface and request bytes but add build and release coordination. Cache only when the result and authorization scope are clear. Monitor rejected cost, deepest accepted query, aliases, downstream calls, memory, and latency by operation ID without logging private query variables.',
    failure='The server limits query depth to four and accepts a request with 600 aliases at depth two. It exhausts worker time while staying under the depth rule. Add breadth and weighted cost bounds. Another field declares first optional and treats omission as all records; a client accidentally reads an entire tenant. Require pagination and enforce a maximum server-side. Test deep nesting, wide aliases, large first, repeated fragments, recursive relationships, unknown persisted ID, stale operation manifest, and a query whose actual backend cost is much higher than its estimated weight.',
    drill='Price a query for 23 cases with 47 activity items each and compare estimated cost to observed backend calls. Attempt 600 shallow aliases and reject before resolution. Remove first from the activity list and confirm the server supplies a safe bound or returns an error. Register one approved operation ID, change its document during a staged client release, and test old and new manifests. Run the same operation as reviewer 62 without case permission and confirm admission success does not imply data access.',
    decision='Admit operations under measured work budgets before resolving fields, then enforce authorization inside the work.',
    code='function estimatedListWork(parentCount, first, maxFirst) {\n  if (first > maxFirst) return null;\n  return parentCount * first;\n}\nconsole.log(estimatedListWork(23, 47, 40));\n// Output: null',
    checks=['Depth and breadth are both bounded.','Collection arguments have server-side maximums.','Persisted operation IDs do not bypass current authorization.'], mistakes=['Rate limiting only HTTP request count.','Assuming shallow queries are cheap.','Allowing omitted pagination to mean every record.'], related=['web-tech/load-tests-and-capacity-budgets','web-tech/cursor-pagination','web-tech/object-level-authorization-for-reads-and-writes']),
    dict(hub=1, path='web-tech/graphql-mutation-errors-and-pagination-contracts', title='GraphQL Mutation Errors and Pagination Contracts', summary='Make writes idempotent where needed and distinguish expected outcomes from execution failures.',
    definition='A GraphQL mutation expresses a write in a typed schema, but it still needs the same server transaction, authorization, idempotency, and version checks as any other API. Expected outcomes such as a stale revision or validation failure can be represented as typed result variants; unexpected execution faults belong in the response error channel with safe messages. GraphQL responses may contain both data and errors, so clients must not equate a successful HTTP status with a successful domain action. List reads need stable pagination rules, usually a cursor tied to a deterministic sort and filters, rather than an unbounded array hidden behind a field.',
    case='Reviewer 29 edits case 47 from revision 6 to 7 through updateCase. The mutation takes an idempotency key and expected revision, checks current case permission, then commits one change and outbox event. A repeated request with the same key returns the original result. Reviewer 62 attempts the same case and gets a safe denied outcome. A stale reviewer request receives a typed conflict with current revision metadata allowed by policy. The case activity connection returns 23 rows sorted by immutable event time and ID, plus an opaque end cursor. A later page continues from that position without repeating rows even when new activity arrives.',
    implementation='Validate input shape and business rules before mutation, then execute authorization, optimistic concurrency, write, and side-effect intent in one transaction. Scope idempotency keys to actor and operation. Model expected validation and conflict results explicitly if clients need field-level handling; use execution errors for faults and avoid private internal messages. A client should inspect both the returned result and errors, and should not blindly retry every mutation after a timeout. For a connection, fix sort order and filters, cap page size, and encode the position in an opaque cursor with integrity protection when its contents need trust. Recheck authorization on each page. Document what happens when items are inserted or deleted during pagination.',
    cost='A versioned mutation is O(1) indexed record work plus validation and any outbox writes; idempotency storage adds one keyed result. Keyset pagination can keep page lookup near O(log n plus k) for k returned rows with a suitable index, whereas deep offset pagination can grow with skipped rows. An opaque cursor adds encode and verification work but prevents clients from relying on internal IDs. Typed result variants add schema surface yet make expected recovery explicit. Measure conflict rate, duplicate mutation attempts, page gaps or repeats, and client behavior when a response contains data plus errors.',
    failure='The client sees HTTP 200 and clears its edit form even though updateCase returned a stale-revision result. Handle the typed result and preserve user input for comparison. Another resolver writes the case, then fails before queuing its notice; a retry writes again because no idempotency key was recorded. Commit intent and result together. A paginated activity field sorts only by timestamp, so simultaneous events share a cursor position and one disappears. Add an immutable tie-breaker. Test duplicated requests, timeout after commit, revoked access, stale revision, partial errors, equal timestamps, inserted rows, and changed filters between pages.',
    drill='Update case 47 from revision 6 using one idempotency key, repeat the same mutation, and verify one write and one outbox item. Submit a stale revision and inspect the typed conflict without losing the client draft. Run an activity query with 23 records, including equal timestamps, across several bounded pages. Insert a newer event between pages and confirm the continuation rule. Change the filter while reusing a cursor and reject or restart according to the documented cursor scope.',
    decision='Treat GraphQL writes and pages as domain contracts with explicit retries, errors, authorization, and stable continuation.',
    code='function mutationOutcome(expectedRevision, currentRevision) {\n  return expectedRevision === currentRevision ? "applied" : "conflict";\n}\nconsole.log(mutationOutcome(6, 7));\n// Output: conflict',
    checks=['HTTP success does not hide a domain conflict.','A repeated idempotent mutation has one effective write.','Cursor pages use a stable sort and bounded size.'], mistakes=['Treating every GraphQL response with data as full success.','Retrying a timed-out write with a new identity.','Using a timestamp-only cursor when values can tie.'], related=['web-tech/idempotent-write-requests','web-tech/optimistic-mutations-and-rollback','web-tech/cursor-pagination']),
])

